/-- Owner answer: an input with no artifact that can be chosen (usage-bearing and not excluded) raises. -/
def NoEligibleRaises (f : Impl) : Prop :=
  ∀ x : Input, Legal x → (∀ a ∈ x, eligible a = false) → f x = none

/-- Owner answer: an input with no artifact that can be chosen (usage-bearing and not excluded) raises, when the input has at least one artifact. The empty input gives an empty result. -/
def NoEligibleRaises (f : Impl) : Prop :=
  ∀ x : Input, Legal x → x ≠ [] → (∀ a ∈ x, eligible a = false) → f x = none

/-- Owner answer: on a legal input the function does not raise. A payload text that `int` cannot parse (for example in a token field) does not stop the run; the function still gives a result. -/
def NeverRaises (f : Impl) : Prop :=
  ∀ x : Input, Legal x → ∃ rows, f x = some rows
